/// <summary>
/// This is a service class
/// CB355_DutyRoll
/// </summary>
internal final class METVendClaimProcessHelper
{
    RecordInsertList                recordInsertList;
    RecordInsertList                ledgerJournalTransRecordList;
    GUPItemBasePrice                itemBasePrice;
    GUPItemBasePriceCurrentActive   itemBasePriceCurrentActive;
    NumberSeq                       numberSeq;
    GUPParameters                   gupParameters;
    METExciseDutyParameteres        exciseDutyParameteres;
    CostingVersion                  costingVersion;
    InventSiteId                    siteId;
    TransDate                       activationDate;
    METDutyRollVariance             dutyRollVariance;
    LedgerJournalTable              ledgerJournalTable;
    LedgerJournalName               ledgerjournalName;

    #OCCRetryCount

}

Method.Source:
    /// <summary>
    /// pass VFD Variance
    /// </summary>
    /// <param name = "_dutyRollVariance">METDutyRollVariance</param>
    /// <returns>METDutyRollVariance</returns>
    public METDutyRollVariance parmDutyRollVariance(METDutyRollVariance   _dutyRollVariance)
    {
        dutyRollVariance = _dutyRollVariance;

        return dutyRollVariance;
    }

/// <summary>
///init default parameters
/// </summary>
public void initParameters()
{
    this.getClaimLineIdNumberSeq();
    recordInsertList    = new RecordInsertList(tableNum(METVendorClaimTable));
    gupParameters       = GUPParameters::find();
}

/// <summary>
/// Init Excise Duty parameters
/// </summary>
public void initLedgerJournalParm()
{
    exciseDutyParameteres           = METExciseDutyParameteres::find();
    if (!exciseDutyParameteres.ExciseClaimJournalName)
    {
        throw error("@MET:ExciseClaimJournalNameNull");
    }
    if (!exciseDutyParameteres.ExciseClaimNumberSequence)
    {
        throw error("@MET:ExciseClaimNumberSequenceNull");
    }
    ledgerJournalName               = LedgerJournalName::find(exciseDutyParameteres.ExciseClaimJournalName);
    ledgerJournalTransRecordList    = new RecordInsertList(tableNum(LedgerJournalTrans));
}

    /// <summary>
    /// init from DutyRollVariance
    /// </summary>
    /// <returns>METVendorClaimTable</returns>
    private METVendorClaimTable initVendorClaimFromDutyRollVariance()
    {
        METVendorClaimTable     vendorClaimTable;
        LedgerJournalTrans      ledgerJournalTrans;
        
        ledgerJournalTrans = this.createLedgerJournalTrans();
        ledgerJournalTransRecordList.add(ledgerJournalTrans);

        vendorClaimTable.clear();
        vendorClaimTable.ClaimLineId    = numberSeq.num();
        vendorClaimTable.ClaimType      = MetVendClaimType::VFDVariance;
        vendorClaimTable.SiteId         = dutyRollVariance.Site;
        vendorClaimTable.ItemId         = dutyRollVariance.ItemId;
        vendorClaimTable.modifiedField(fieldNum(METVendorClaimTable, ItemId));
        vendorClaimTable.ClaimAmount    = dutyRollVariance.ClaimAmount;
        vendorClaimTable.VendAccount    = dutyRollVariance.VendAccount;
        vendorClaimTable.ClaimDate      = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
        vendorClaimTable.VFDCurrent     = dutyRollVariance.CurrentDutyValue;
        vendorClaimTable.VFDReceived    = dutyRollVariance.DutyValue;
        vendorClaimTable.JournalId      = ledgerJournalTable.JournalNum;
        vendorClaimTable.LedgerDimension = ledgerJournalName.OffsetLedgerDimension;
        vendorClaimTable.ClaimInvoiceId = ledgerJournalTrans.Invoice;
            
        return vendorClaimTable;
    }

    /// <summary>
    /// Number sequence for Vendor claim lineId
    /// </summary>
    private void getClaimLineIdNumberSeq()
    {
        NumberSequenceReference numberSequenceReference;
        NumberSequenceTable     numberSequenceTable;

        numberSequenceReference = GUPParameters::numRefMETVendClaimLineId();
        numberSequenceTable = NumberSequenceTable::find(numberSequenceReference.NumberSequenceId);

        if (numberSequenceTable)
        {
            if (numberSequenceTable.Manual == NoYes::Yes)
            {
                throw error(strFmt("@SYS131762", "@MET:VendorClaimLineId"));
            }
            else
            {
                numberSeq = NumberSeq::newGetNum(numberSequenceReference);
            }
        }

        if (numberSeq == null)
        {
            throw error(strfmt("@GLS111556", new DictType(extendedtypenum(METVendClaimLineId)).label(), "@GlobalUnifiedPricing:GUPParameters"));
        }
    }

    /// <summary>
    /// Create journal for each site
    /// </summary>
    public void createLedgerJournalTable()
    {
        ledgerJournalTable.clear();
        ledgerJournalTable.initValue();
        ledgerJournalTable.initFromLedgerJournalName(ledgerJournalName.JournalName);
        ledgerJournalTable.insert();

    }

    /// <summary>
    /// Create journal lines for claims
    /// </summary>
    /// <returns>LedgerJournalTrans</returns>
    private LedgerJournalTrans createLedgerJournalTrans()
    {
        LedgerJournalTrans ledgerJournalTrans;
       
        ledgerJournalTrans.clear();
        ledgerJournalTrans.initValue();
        ledgerJournalTrans.JournalNum       = ledgerJournalTable.JournalNum;
        ledgerJournalTrans.Voucher          = this.getClaimJournalVoucherNumberSeq().voucher();
        ledgerJournalTrans.Invoice          = this.getClaimInvoiceNumberSeq().num();
        ledgerJournalTrans.AccountType      = LedgerJournalACType::Vend;
        ledgerJournalTrans.parmAccount(dutyRollVariance.VendAccount);
        ledgerJournalTrans.DocumentDate     = DateTimeUtil::getToday(DateTimeUtil::getCompanyTimeZone());
        ledgerJournalTrans.TransDate        = DateTimeUtil::getToday(DateTimeUtil::getCompanyTimeZone());
        ledgerJournalTrans.CurrencyCode     = ledgerJournalTable.CurrencyCode;
        ledgerJournalTrans.AmountCurDebit   = dutyRollVariance.ClaimAmount;
        ledgerJournalTrans.OffsetAccountType        = LedgerJournalACType::Ledger;
        ledgerJournalTrans.OffsetLedgerDimension    = LedgerDimensionFacade::serviceCreateLedgerDimension(ledgerJournalName.OffsetLedgerDimension);
        ledgerJournalTrans.TaxGroup                 = VendTable::find(dutyRollVariance.VendAccount).TaxGroup;
        ledgerJournalTrans.TaxItemGroup             = InventTableModule::find(dutyRollVariance.ItemId, ModuleInventPurchSales::Purch).TaxItemGroupId;
        if (!ledgerJournalTrans.CurrencyCode)
        {
            ledgerJournalTrans.CurrencyCode = ledgerJournalTable.CurrencyCode;
        }

        return ledgerJournalTrans;

    }

/// <summary>
/// Get the claim voucher number sequence
/// </summary>
/// <returns>Voucher numebr sequence</returns>
private NumberSeq getClaimJournalVoucherNumberSeq()
{
    return NumberSeq::newGetVoucherFromCode(NumberSequenceTable::find(ledgerJournalName.NumberSequenceTable).NumberSequence,
                                            NumberSeqScopeFactory::createDefaultScope(),
                                            false);
}

/// <summary>
/// Get the claim invoice number sequence
/// </summary>
/// <returns>invoice numebr sequence</returns>
private NumberSeq getClaimInvoiceNumberSeq()
{
    return NumberSeq::newGetNumFromId(exciseDutyParameteres.ExciseClaimNumberSequence);

}

/// <summary>
/// Posts the claim journal
/// </summary>
private void postClaimJournal()
{
    if (ledgerJournalTable)
    {
        LedgerJournalPost::postJournal(ledgerJournalTable, NoYes::Yes);
    }
}

/// <summary>
/// main process for Vendor claims from DutyRollVariance
/// </summary>
public void processForDutyVariance()
{
    if(ledgerJournalTable.RecId
    && dutyRollVariance.DutyValue != dutyRollVariance.CurrentDutyValue)
    {
        recordInsertList.add(this.initVendorClaimFromDutyRollVariance());
    }
    
}

/// <summary>
/// post Claim general journal
/// </summary>
public void postLedgerJournal()
{
    if (ledgerJournalTable.RecId)
    {
        recordInsertList.insertDatabase();
        ledgerJournalTransRecordList.insertDatabase();
        try
        {
            if(ledgerJournalTable.numOfLines() > 0)
            {
                this.postClaimJournal();
            }
        }
        catch (Exception::Error)
        {
            error("@MET:VendClaimJournalPostingError");
            exceptionTextFallThrough();
        }
    }
}
